import json,pathlib,html
P=pathlib.Path(__file__).resolve().parent
D=json.loads((P/'diagnostics.json').read_text())
def n(v):return '—' if v is None else f'{v:.3f}'
def pct(v):return '—' if v is None else f'{100*v:.1f}%'
def esc(v):return html.escape(str(v))
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
raw=[]
for key in ['ipsae','iptm','foldx','energy_original','energy_relaxed','sc_original','sc_relaxed','hbond_original','hbond_relaxed','binder_length']:
 a,b=[next(v for v in D['feature_distributions'] if v['feature']==key and v['antigen']==ag) for ag in ['egfr','trem2']]
 raw.append([esc(a['label']),n(a['auc']),n(b['auc']),n(a['B']['median']),n(a['NB']['median']),f'{n(a["bootstrap"]["lower"])}–{n(a["bootstrap"]["upper"])}'])
summary=[];capacity=[];foldrows=[];coef=[];allrows=[]
for v in D['model_comparisons']:
 stage=v['stage'].title();fs=v['feature_set']
 for typ,label in [('within','Train EGFR → test unseen EGFR families'),('transfer','Train TREM2 → test EGFR')]:
  m=v['matched'][typ];c=m.get('fixed_half')
  allrows.append([stage,esc(fs),label,n(m['auroc']),n(m['ap']),pct(c['recall']) if c else 'N/A',pct(c['precision']) if c else 'N/A',f'{c["selected"]}/378' if c else 'N/A'])
  if fs!='E':continue
  summary.append([stage,label,n(m['auroc']),pct(c['recall']),pct(c['precision']),str(c['tp']),str(c['fp']),f'{c["selected"]}/378'])
  for budget in ['0.1','0.2']:
   b=m['budgets'][budget];capacity.append([stage,label,f'{100*float(budget):.0f}%',str(b['selected']),f'{b["tp"]}/53',pct(b['recall']),pct(b['precision']),str(b['fp'])])
 if fs=='E':
  for f in v['folds']:foldrows.append([stage,f['fold'],f'{f["binders"]}/{f["n"]}',n(f['within']['auroc']),n(f['transfer']['auroc']),n(f['within']['ap']),n(f['transfer']['ap'])])
 if fs in ['A','E']:
  for f in v['fits']:
   ft=f['fit'];coef.append([stage,fs,f['training'],f['fold'],f'{f["train_binders"]}/{f["train_n"]}',str(f['positive_training_families']),n(ft['intercept']),'<br>'.join(f'{esc(k)}: {n(c)}' for k,c in zip(ft['features'],ft['coefficients_standardized']))])
policy=[]
for v in D['model_comparisons']:
 if v['feature_set']!='E':continue
 for key,label in [('within_summary','Within EGFR'),('transfer_summary','TREM2 → EGFR')]:
  s=v[key];m=s['selected_pooled'];full=s['full_policy_coverage']
  policy.append([v['stage'].title(),label,f'{s["feasible_folds"]}/{s["total_folds"]}',f'{s["policy_covered_n"]}/378',pct(m['recall']) if m and full else 'Unavailable for full cohort',pct(m['precision']) if m and full else 'Unavailable for full cohort',f'{m["selected"]}/378' if m and full else '—'])
source=''.join(f'<li><a href="../{esc(f)}">{esc(f)}</a><code>{h}</code></li>' for f,h in D['source_sha256'].items())
css='''*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#0c1319;color:#e4edf3;font:16px/1.55 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:36px 30px 80px}header{padding:18px 0 30px;border-bottom:1px solid #344857}a{color:#63d7c7}h1{font-size:clamp(30px,4vw,52px);line-height:1.12;margin:16px 0}h2{font-size:25px;margin:0 0 12px}h3{font-size:20px}p{max-width:1050px}.eyebrow{color:#7dc9c5;text-transform:uppercase;letter-spacing:.13em;font-size:12px}.lead{font-size:21px;max-width:1120px}.muted,.note{color:#acc0ce}.note{font-size:14px}.callout{border-left:4px solid #4ac7b3;padding:14px 20px;background:#112a2a;margin:20px 0}.warning{border-color:#e9b673;background:#30271a}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:28px 0}.card{padding:20px;border:1px solid #344857;border-radius:12px;background:#101d26}.big{font-size:36px;font-variant-numeric:tabular-nums}section{padding:32px 0;border-bottom:1px solid #263946}.scroll{overflow-x:auto;border:1px solid #344857;border-radius:10px;margin:18px 0}table{width:100%;border-collapse:collapse;font-size:14px}th{background:#182b36;text-align:left}th,td{padding:12px;border-bottom:1px solid #29404d;vertical-align:top}td{font-variant-numeric:tabular-nums}tr:hover td{background:#152733}img{width:100%;display:block;height:auto}figure{margin:24px 0}figcaption{color:#acc0ce;font-size:14px;padding:8px}details{padding:14px 0}summary{cursor:pointer;color:#72dbcc;font-weight:600}code{display:block;font-size:11px;overflow-wrap:anywhere;color:#adbdc9}nav{display:flex;gap:20px;flex-wrap:wrap}li{margin-bottom:12px}.small{font-size:13px}.pill{display:inline-block;padding:3px 9px;border-radius:12px;background:#263b43;font-size:12px} @media(max-width:700px){main{padding:24px 16px}.cards{grid-template-columns:1fr}.lead{font-size:18px}td,th{padding:9px}h2{font-size:22px}}'''
htmltext=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Why is EGFR recall low? · ProteinBase diagnosis</title><style>{css}</style></head><body><main>
<header><div class="eyebrow">ProteinArena · Evaluator diagnosis · 13 October 2026</div><h1>Higher recall is not always<br>better discrimination.</h1><p class="lead">EGFR scores overlap between binders and nonbinders, but retain useful ranking information. For the original five-feature model, TREM2 training mostly changes which designs are selected; it does not improve the matched aggregate AUROC. The relaxed model shows a real descriptive ranking improvement.</p><nav><a href="../index.html#preparation-comparison">← Evaluator comparison</a><a href="#overlap">Score overlap</a><a href="#matched">Same-test comparison</a><a href="#capacity">Equal screening capacity</a><a href="#families">Families</a><a href="#methods">Methods & data</a></nav></header>
<div class="cards"><div class="card"><div class="muted">EGFR binders / eligible designs</div><div class="big">53 / 378</div><div>14.0% prevalence · 9 positive families</div></div><div class="card"><div class="muted">Binders in two EGFR families</div><div class="big">46 / 53</div><div>32 + 14 binders; 144 nonbinders in those same families</div></div><div class="card"><div class="muted">Original model E · matched AUROC</div><div class="big">0.630 → 0.629</div><div>EGFR-trained → TREM2-trained, same EGFR folds</div></div></div>
<div class="callout"><strong>What transfer means here:</strong> train on TREM2, then test on EGFR. There is no subsequent EGFR fine-tuning. For a fair model comparison, the main analysis holds feature set E fixed: energy + shape complementarity + interface H-bonds + original ipSAE + original ipTM. This is distinct from the evaluator's training-selected A–E procedure.</div>
<section id="overlap"><h2>1. Are EGFR binder and nonbinder scores similar?</h2><p>They overlap substantially, but are not indistinguishable. EGFR median ipSAE is <strong>0.688 for binders</strong> versus <strong>0.395 for nonbinders</strong>. Their middle 50% ranges overlap: 0.469–0.799 versus 0.000–0.671. TREM2 has stronger confidence-score separation, while original Rosetta energy separates EGFR better than TREM2. The hypothesis does not hold equally for every metric.</p>
<figure><a href="feature_overlap.svg"><img src="feature_overlap.svg" alt="EGFR binder and nonbinder empirical cumulative score distributions"></a><figcaption>Each curve shows the fraction of one class at or below a score. Overlapping curves indicate overlapping distributions. Every eligible design is included. Energy axes use a symmetric log display to retain extreme values; AUROC uses the untransformed score.</figcaption></figure>
{table(['Raw measurement','EGFR AUROC','TREM2 AUROC','EGFR B median','EGFR NB median','EGFR 95% family-bootstrap interval'],raw)}
<p class="note">These are descriptive, full-cohort univariate AUROCs—not held-out logistic regression results. Confidence/shape scores are oriented higher-is-favorable; energies lower-is-favorable. Higher H-bond count and binder length are descriptive orientations only. Family-bootstrap intervals resample whole families and remain uncertain with just nine positive EGFR families.</p></section>
<section id="matched"><h2>2. Hold the model and EGFR test designs fixed</h2><p>The original E model's recall rises from 0% to 47.2% at a probability cutoff of 0.5, while matched AUROC remains about 0.63. It selects 104 designs instead of one, and adds 79 false positives. This supports a change in operating point and score distribution, not a large aggregate ranking gain. Individual folds still differ.</p>
{table(['Coordinates','Training / testing','Matched AUROC','Recall at 0.5','Precision at 0.5','True binders found','False positives','Selected'],summary)}
<p>The relaxed E model is an important exception: matched AUROC increases from 0.523 to 0.686. A changed cutoff cannot explain that ranking difference, although it is a retrospective observation with limited family support.</p>
<figure><a href="matched_prediction_diagnostics.svg"><img src="matched_prediction_diagnostics.svg" alt="Matched fold ROC curves, predicted probability distributions and recall versus selection fraction for original and relaxed E models"></a><figcaption>ROC panels show each of the three EGFR test folds separately; line styles identify folds. The legend's AUROC is sample-weighted across those folds. In probability panels, solid lines are B and dashed lines NB; colors identify the training source. The 0.5 line is a diagnostic cutoff, not a universal biological threshold.</figcaption></figure>
<details><summary>Individual folds and all saved feature combinations</summary>{table(['Coordinates','EGFR fold','B / n','EGFR-trained AUC','TREM2-trained AUC','EGFR-trained AP','TREM2-trained AP'],foldrows)}<p>A=energy; B=energy+shape; C=energy+H-bonds; D=energy+shape+H-bonds; E=D+ipSAE+ipTM. Reference4=ipSAE+ipTM+FoldX+Rosetta energy. A–E/reference4/control models use the existing logistic fits. Raw energy is the unfitted favorable-direction score.</p>{table(['Coordinates','Model','Training / testing','Matched AUC','Matched AP','Recall at 0.5','Precision at 0.5','Selected'],allrows)}</details>
<h3>The source-selected precision rule does not transfer reliably</h3><p>The TREM2-selected original-E cutoff is 0.0993. On EGFR it finds 46/53 binders (86.8% recall), but selects 275 designs, including 229 nonbinders: only 16.7% precision. The intended 50% validation precision floor is not achieved on this target.</p>
{table(['Coordinates','Evaluation','Feasible training folds','Policy coverage','Held-out recall','Held-out precision','Selected'],policy)}
<p class="note">Unavailable within-EGFR policy results are not zero recall: some or all training folds could not find a nonempty selection meeting the 50% validation precision rule. The fixed 0.5 diagnostic above remains available for all 378 rows.</p></section>
<section id="capacity"><h2>3. Does transfer find more binders for the same screening effort?</h2><p>At approximately 20% capacity, both methods select <strong>77 of 378 designs</strong>. Original E finds <strong>16 binders with EGFR training versus 14 with TREM2 training</strong>. Relaxed E finds <strong>6 versus 18</strong>. This reinforces the distinction: the original model's recall advantage disappears at this capacity; the relaxed transfer model retains an advantage.</p>
{table(['Coordinates','Training / testing','Budget per fold','Selected','Binders found','Recall','Precision','False positives'],capacity)}
<p class="note">Fixed exploratory 10% and 20% budgets were chosen for this diagnosis, after earlier test results had already been inspected. They are not preregistered study endpoints. We take the top ceil(budget × fold size) predictions within each saved test fold and retain complete tied-score blocks. Labels are used only to evaluate the resulting selections. These budgets are diagnostic examples, not replacements for the frozen 50% precision policy or test-selected optima.</p></section>
<section id="families"><h2>4. Few independent positive families limit EGFR learning</h2><p>EGFR's two largest positive families contain 32/128 and 14/62 binders. Those families also contain many nonbinders, so knowing the family does not solve the task. But when a family is held out, the model loses a large share of its positive evidence. One EGFR outer-training set has only two binder-containing families; its inner-training partitions each have only one.</p>
<figure><a href="family_support.svg"><img src="family_support.svg" alt="Binder counts across EGFR and TREM2 positive families"></a><figcaption>EGFR: 53 binders in 9 families. Full TREM2: 37 binders in 27 families. After cross-target family exclusion, the actual transfer training set is 85 TREM2 designs, with 36 binders in 26 positive families.</figcaption></figure>
<p>Class prevalence also changes: 42.4% in the actual TREM2 training set versus 14.0% in the EGFR test set. The logistic models are unweighted. This can contribute to a changed probability scale, but different learned slopes, feature distributions and assays also change. These observations do not establish prevalence as the sole cause.</p>
<details><summary>Inspect learned coefficients and training support</summary><p>Saved standardized coefficients; no fits repeated. Positive energy coefficients mean the learned model reverses the physical lower-energy preference. Relaxed energy-only EGFR folds have coefficients +0.149, −0.478 and −1.006, illustrating family-dependent instability. Multifeature coefficients are conditional on other correlated inputs and are not causal effects.</p>{table(['Coordinates','Model','Training source','Fold','Training B / n','Positive training families','Intercept','Standardized coefficients'],coef)}</details>
<div class="callout warning"><strong>Critical uncertainty:</strong> EGFR uses BLI_S04_R1, while TREM2 uses SPR_S01_R1. Target identity and assay cohort are completely confounded. Exact modeled sequences are verified, but equivalence to every experimental construct is unresolved. These data cannot determine whether biology, assay context, scaffold composition or prevalence explains each difference.</div></section>
<section><h2>What this means for ProteinArena</h2><p><strong>Do not promote an evaluator based on recall alone.</strong> The EGFR overlap hypothesis is partly supported; sparse positive-family evidence and a more permissive transferred decision function are also important. Original E shows no matched aggregate ranking gain, while relaxed E shows a promising but uncertain transfer gain. Neither finding establishes a generally reliable arena judge.</p><p>The smallest next validation is to freeze a candidate evaluator and selection rule, then test genuinely new EGFR binder families. Use a separate calibration set if an EGFR-specific probability cutoff is needed, and evaluate once on an untouched family-held-out test set. More independent positive families are more informative than repeatedly refitting the same two dominant families. No new training or molecular jobs were started for this diagnosis.</p></section>
<section id="methods"><h2>Reproducibility and independent review</h2><p>All 467 input rows and all existing results are unchanged. This report reads saved predictions and recomputes comparisons on identical EGFR test partitions. It performs no prediction, relaxation, model fitting, calibration or held-out threshold search. Cluster intervals use 1,000 family resamples with seed 42; they are descriptive and do not include model-training variability. The observed test sets have already been inspected, so this is exploratory analysis.</p><p>Two independent analyses and three reviewers checked the principal claims. This was a reduced review panel because the session's agent-creation limit prevented the full council workflow. Both analyses agreed on the numerical results; reviewers emphasized that similar aggregate AUROC does not imply identical rankings, and that class prevalence cannot be isolated as the cause. All three ranked Response B first for clearer handling of family support and confounding (mean rank B=1, A=2).</p><p><a href="diagnostics.json">Computed diagnostics and saved prediction slices</a> · <a href="analyze.py">Analysis script</a> · <a href="build_report.py">Report builder</a> · <a href="independent_audit.json">Independent numerical audit (1,601 checks)</a></p><details><summary>Immutable source hashes</summary><ul>{source}</ul></details><p class="small muted">Run: OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 /LOCAL_HOME/miniconda3/bin/python3 analyze.py<br>Then run build_report.py with the same Python runtime. Figures are available as SVG and PNG alongside this report.</p></section>
</main></body></html>'''
(P/'index.html').write_text(htmltext)
print(P/'index.html')
